using Ocelot.DependencyInjection;using Ocelot.Middleware;using Serilog;var b=WebApplication.CreateBuilder(args);b.Host.UseSerilog((c,l)=>l.ReadFrom.Configuration(c.Configuration).WriteTo.Console());b.Configuration.AddJsonFile("ocelot.json",optional:false,reloadOnChange:true);b.Services.AddOcelot(b.Configuration);var app=b.Build();app.UseSerilogRequestLogging();await app.UseOcelot();app.Run();